<details class="qms-folder-actions" @click.outside="$el.open=false"><summary :aria-label="'Actions for folder ' + folder.name">&hellip;</summary><div class="qms-action-popover"><button type="button" @click="$el.closest('details').open=false;openBrowseFolder(folder)">Open</button><button type="button" @click="$el.closest('details').open=false;toggleFolderStar(folder)" x-text="folder.isStarred ? 'Unstar' : 'Star'"></button><button type="button" @click="$el.closest('details').open=false;inspectFolder(folder)">View Details</button></div></details>
